<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=1200, initial-scale=1">
<title>Samsung Galaxy Ecosystem 2025 - Poster</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap');

  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    width: 1200px;
    min-height: 1800px;
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
    background: linear-gradient(180deg, #050a1a 0%, #0a1628 30%, #0d1f3c 60%, #091428 100%);
    color: #ffffff;
    overflow: hidden;
  }

  .poster {
    width: 1200px;
    min-height: 1800px;
    padding: 0;
    position: relative;
    overflow: hidden;
  }

  /* Ambient glow effects */
  .poster::before {
    content: '';
    position: absolute;
    top: -200px;
    left: 50%;
    transform: translateX(-50%);
    width: 800px;
    height: 800px;
    background: radial-gradient(ellipse, rgba(30, 90, 200, 0.15) 0%, transparent 70%);
    pointer-events: none;
  }

  .poster::after {
    content: '';
    position: absolute;
    bottom: 200px;
    left: 50%;
    transform: translateX(-50%);
    width: 1000px;
    height: 600px;
    background: radial-gradient(ellipse, rgba(30, 90, 200, 0.08) 0%, transparent 70%);
    pointer-events: none;
  }

  /* Top bar */
  .top-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 36px 60px 20px;
    position: relative;
    z-index: 2;
  }

  .samsung-logo {
    font-size: 28px;
    font-weight: 800;
    letter-spacing: 8px;
    text-transform: uppercase;
    color: #ffffff;
  }

  .ai-badge-top {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 13px;
    font-weight: 600;
    letter-spacing: 2px;
    color: rgba(255,255,255,0.6);
    text-transform: uppercase;
  }

  .ai-badge-top .dot {
    width: 6px;
    height: 6px;
    background: #4a90d9;
    border-radius: 50%;
  }

  /* Hero Section */
  .hero {
    text-align: center;
    padding: 30px 60px 40px;
    position: relative;
    z-index: 2;
  }

  .hero-year {
    font-size: 14px;
    font-weight: 600;
    letter-spacing: 6px;
    text-transform: uppercase;
    color: rgba(255,255,255,0.4);
    margin-bottom: 12px;
  }

  .hero-title {
    font-size: 52px;
    font-weight: 900;
    line-height: 1.1;
    letter-spacing: -1px;
    margin-bottom: 8px;
    background: linear-gradient(135deg, #ffffff 0%, #b8d4f0 50%, #4a90d9 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  .hero-subtitle {
    font-size: 18px;
    font-weight: 400;
    color: rgba(255,255,255,0.55);
    max-width: 700px;
    margin: 0 auto 30px;
    line-height: 1.5;
  }

  /* Flagship launches */
  .flagships {
    display: flex;
    justify-content: center;
    gap: 40px;
    padding: 0 60px 10px;
    position: relative;
    z-index: 2;
  }

  .flagship-card {
    flex: 0 0 460px;
    background: linear-gradient(135deg, rgba(255,255,255,0.06) 0%, rgba(255,255,255,0.02) 100%);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 20px;
    padding: 36px 40px;
    position: relative;
    overflow: hidden;
    backdrop-filter: blur(10px);
  }

  .flagship-card::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 2px;
    background: linear-gradient(90deg, transparent, #c8a050, #d4a853, transparent);
  }

  .flagship-card .new-tag {
    display: inline-block;
    padding: 4px 14px;
    background: linear-gradient(135deg, #c8a050, #d4a853);
    color: #0a1628;
    font-size: 11px;
    font-weight: 800;
    letter-spacing: 2px;
    text-transform: uppercase;
    border-radius: 4px;
    margin-bottom: 16px;
  }

  .flagship-card .product-name {
    font-size: 28px;
    font-weight: 800;
    letter-spacing: -0.5px;
    margin-bottom: 6px;
    color: #ffffff;
  }

  .flagship-card .product-series {
    font-size: 13px;
    font-weight: 600;
    letter-spacing: 3px;
    text-transform: uppercase;
    color: #c8a050;
    margin-bottom: 14px;
  }

  .flagship-card .product-desc {
    font-size: 14px;
    line-height: 1.65;
    color: rgba(255,255,255,0.5);
  }

  .flagship-card .product-icon {
    position: absolute;
    bottom: 20px;
    right: 30px;
    font-size: 64px;
    opacity: 0.06;
    color: #c8a050;
  }

  .flagship-card.phone .product-icon::after { content: ''; }
  .flagship-card.buds .product-icon::after { content: ''; }

  /* Metrics row */
  .metrics-row {
    display: flex;
    justify-content: center;
    gap: 24px;
    padding: 36px 60px 10px;
    position: relative;
    z-index: 2;
  }

  .metric-badge {
    flex: 0 0 auto;
    text-align: center;
    padding: 20px 36px;
    background: linear-gradient(135deg, rgba(74,144,217,0.1) 0%, rgba(74,144,217,0.04) 100%);
    border: 1px solid rgba(74,144,217,0.15);
    border-radius: 14px;
    min-width: 200px;
  }

  .metric-badge .metric-value {
    font-size: 36px;
    font-weight: 900;
    color: #4a90d9;
    letter-spacing: -1px;
    line-height: 1;
    margin-bottom: 6px;
  }

  .metric-badge .metric-label {
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: rgba(255,255,255,0.45);
  }

  /* Section divider */
  .section-divider {
    display: flex;
    align-items: center;
    gap: 16px;
    padding: 36px 60px 8px;
    position: relative;
    z-index: 2;
  }

  .section-divider .line {
    flex: 1;
    height: 1px;
    background: linear-gradient(90deg, rgba(74,144,217,0.3), rgba(74,144,217,0.05));
  }

  .section-divider .line.right {
    background: linear-gradient(90deg, rgba(74,144,217,0.05), rgba(74,144,217,0.3));
  }

  .section-divider .label {
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 4px;
    text-transform: uppercase;
    color: rgba(74,144,217,0.6);
    white-space: nowrap;
  }

  /* AI Section */
  .ai-section {
    padding: 20px 60px 10px;
    text-align: center;
    position: relative;
    z-index: 2;
  }

  .ai-title {
    font-size: 26px;
    font-weight: 800;
    margin-bottom: 12px;
    background: linear-gradient(135deg, #4a90d9, #7ab5e8, #4a90d9);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  .ai-desc {
    font-size: 14px;
    color: rgba(255,255,255,0.45);
    max-width: 800px;
    margin: 0 auto 24px;
    line-height: 1.6;
  }

  .ai-brands {
    display: flex;
    justify-content: center;
    gap: 30px;
  }

  .ai-brand-pill {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 10px 24px;
    background: rgba(74,144,217,0.08);
    border: 1px solid rgba(74,144,217,0.2);
    border-radius: 100px;
    font-size: 14px;
    font-weight: 600;
    color: #7ab5e8;
  }

  .ai-brand-pill .ai-icon {
    width: 18px;
    height: 18px;
    background: linear-gradient(135deg, #4a90d9, #7ab5e8);
    border-radius: 4px;
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .ai-brand-pill .ai-icon svg {
    width: 12px;
    height: 12px;
    fill: #fff;
  }

  /* Category Table */
  .category-table-section {
    padding: 20px 60px 30px;
    position: relative;
    z-index: 2;
  }

  .category-table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 0 6px;
  }

  .category-table thead th {
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 3px;
    text-transform: uppercase;
    color: rgba(255,255,255,0.35);
    padding: 0 20px 12px;
    text-align: left;
    border-bottom: 1px solid rgba(255,255,255,0.06);
  }

  .category-table thead th:last-child {
    text-align: center;
  }

  .category-table tbody tr {
    background: rgba(255,255,255,0.025);
    transition: background 0.2s;
  }

  .category-table tbody tr.highlight {
    background: rgba(200,160,80,0.06);
  }

  .category-table tbody td {
    padding: 13px 20px;
    font-size: 14px;
    font-weight: 500;
    color: rgba(255,255,255,0.75);
    vertical-align: middle;
  }

  .category-table tbody td:first-child {
    border-radius: 8px 0 0 8px;
    font-weight: 700;
    color: rgba(255,255,255,0.5);
    font-size: 12px;
    letter-spacing: 1px;
    text-transform: uppercase;
  }

  .category-table tbody td:last-child {
    border-radius: 0 8px 8px 0;
    text-align: center;
  }

  .status-new {
    display: inline-block;
    padding: 3px 12px;
    background: linear-gradient(135deg, #c8a050, #d4a853);
    color: #0a1628;
    font-size: 10px;
    font-weight: 800;
    letter-spacing: 2px;
    text-transform: uppercase;
    border-radius: 4px;
  }

  .status-current {
    display: inline-block;
    padding: 3px 12px;
    background: rgba(74,144,217,0.15);
    color: #4a90d9;
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 1px;
    text-transform: uppercase;
    border-radius: 4px;
  }

  .ai-tag {
    display: inline-block;
    margin-left: 6px;
    padding: 2px 8px;
    background: rgba(74,144,217,0.12);
    color: #7ab5e8;
    font-size: 9px;
    font-weight: 700;
    letter-spacing: 1px;
    text-transform: uppercase;
    border-radius: 3px;
    vertical-align: middle;
  }

  /* Footer */
  .poster-footer {
    text-align: center;
    padding: 28px 60px 40px;
    position: relative;
    z-index: 2;
  }

  .footer-tagline {
    font-size: 20px;
    font-weight: 700;
    letter-spacing: 1px;
    color: rgba(255,255,255,0.7);
    margin-bottom: 8px;
  }

  .footer-tagline span {
    color: #4a90d9;
  }

  .footer-sub {
    font-size: 12px;
    color: rgba(255,255,255,0.25);
    letter-spacing: 2px;
    text-transform: uppercase;
  }

  /* Decorative elements */
  .deco-grid {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-image:
      linear-gradient(rgba(74,144,217,0.03) 1px, transparent 1px),
      linear-gradient(90deg, rgba(74,144,217,0.03) 1px, transparent 1px);
    background-size: 60px 60px;
    pointer-events: none;
    z-index: 0;
  }

  .deco-circle {
    position: absolute;
    border-radius: 50%;
    border: 1px solid rgba(74,144,217,0.06);
    pointer-events: none;
    z-index: 0;
  }

  .deco-circle.c1 { width: 400px; height: 400px; top: -100px; right: -100px; }
