const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.setViewportSize({ width: 1200, height: 1800 });
  await page.goto('file:///app/output/poster.html', { waitUntil: 'networkidle' });
  await page.waitForTimeout(1000);

  const body = await page.$('body');
  const box = await body.boundingBox();

  await page.screenshot({
    path: '/app/output/final_poster.png',
    clip: { x: 0, y: 0, width: 1200, height: Math.ceil(box.height) },
    type: 'png'
  });

  console.log(`Screenshot saved: 1200x${Math.ceil(box.height)}`);
  await browser.close();
})();

